class ApproveErrorError(BaseModel):
    """Что случилось; набор полей зависит от code"""

    batch_id: str | None = None
    """При job_running и ошибках пачки: номер задания"""
    blockers: list[str] | None = None
    """При has_blockers — список блокеров"""
    code: str = MISSING
    """Причина для ветвления клиента: - forbidden — нет права proposals.approve; policy_blocked — не пускает политика (error.level); onec_read_only — подключена копия базы только для чтения или 1С запретила запись; - not_found — предложения нет; wrong_status — решение уже принято (error.status); job_running — предложение из задания пачки, которое ещё идёт (error.batch_id); - payload_changed — документ изменился после превью, нужно собрать заново; conflict — такой документ в 1С уже есть; onec_not_found — в 1С пропал объект, на который ссылается документ; - has_blockers — есть блокеры (error.blockers); invalid / invalid_json — неверное тело; batch_too_large — пачка больше предела (error.limit, error.requested); - unavailable — 1С недоступна, документ не записан: повторите позже; write_unknown — 1С не ответила на запись, неизвестно, создан ли документ: повтор безопасен (error.retry_safe, error.marker), но с error.retry_after повтор раньше срока снова получит write_unknown; onec_failed — запись не удалась."""
    document: ProposalDocument | None = None
    gateway: str | None = None
    """При onec_read_only из-за копии базы: snapshot"""
    level: str | None = None
    """При policy_blocked: уровень политики (AutonomyLevel) — HUMAN_ONLY или FORBIDDEN"""
    limit: int | None = None
    """При batch_too_large: предел пачки"""
    marker: str | None = None
    """При write_unknown: метка в комментарии документа 1С ([AI P-000123]) — по ней документ можно найти в 1С руками"""
    message: str = MISSING
    """Текст для человека по-русски — показать как есть"""
    proposal: ProposalCard | None = None
    requested: int | None = None
    """При batch_too_large: сколько предложений прислали"""
    retry_after: int | None = None
    """При write_unknown после слишком раннего повтора: через сколько секунд повтор запишет документ, если его так и не будет (то же в заголовке Retry-After); в 1С этот повтор не писал"""
    retry_safe: bool | None = None
    """При write_unknown: повтор безопасен — сервер сначала найдёт документ по метке"""
    status: str | None = None
    """Статус предложения после попытки (ProposalStatus): при wrong_status и при сбое записи"""
    status_title: str | None = None
    """Статус по-русски — при сбое записи"""
    type: str = MISSING
    """Вид ошибки, как у всех ошибок API: permission_error, not_found_error, conflict_error, invalid_request_error, unavailable_error"""


