class AutomationEventFilter(BaseModel):
    """Какие события хука запускают сценарий; нет — любое"""

    all: list[AutomationFilterCondition] = MISSING
    """Условия (до 20); событие подходит, только если выполнены все. Пустой список — подходит любое событие."""


class AutomationFilterCondition(BaseModel):
    """Одно условие фильтра: значение поля из тела события сравнивается с value."""

    op: AutomationFilterConditionOp = MISSING
    """Как сравнивать значение поля с value. `eq` — равно (строки — без учёта регистра и пробелов по краям; числа — как числа, строка «15000.00» равна 15000); `ne` — не равно, или поля нет; `in` — равно одному из значений списка value; `contains` — строка содержит value (без учёта регистра) или массив содержит элемент, равный value; `exists` — поле есть в теле (с value: false — поля нет); `gt` / `gte` / `lt` / `lte` — число больше / не меньше / меньше / не больше value (строка из цифр сравнивается как число; не число — условие не выполнено)."""
    path: str = MISSING
    """Где в JSON тела события взять значение: имена полей через точку, до 10 уровней; элемент массива — его номером с нуля (`items.0.sum`)."""
    value: AutomationFilterConditionValue | None = None
    """С чем сравнивать: строка (до 500 знаков), число, true/false или null. Для `in` — список до 50 таких значений; для `gt`/`gte`/`lt`/`lte` — число; для остальных — одно значение. Для `exists` не нужно (false — проверить, что поля нет)."""


