class AutomationRunProposal(BaseModel):
    """Предложение (документ для 1С), подготовленное запуском, и итог автоодобрения."""

    attempt: int = MISSING
    """В какой попытке запуска подготовлено: 1 — первая, дальше — повторы"""
    auto: AutomationRunProposalAuto | None = None
    """Итог автоодобрения: `approved` — записано в 1С и проведено само; `draft` — записано само черновиком, без проведения; `skipped` — само не записано, ждёт человека (почему — reason); `failed` — пыталось записать, но запись не удалась (reason). Нет поля — у сценария нет правила автоодобрения или предложение — повтор (duplicate_of)"""
    batch: bool | None = None
    """true — предложение собрано пачкой (выписка, входящие ЭСФ) или выпиской DirectBank, а не отдельным propose_* хода ИИ"""
    code: AutomationRunProposalCode | None = None
    """Машинная причина (при skipped и failed): `status` — предложение уже не ждёт решения (его решили раньше); `kind` — вид документа не входит в правило; `level` — ИИ не доверено записывать такой вид без человека (PUT …/autonomy); `duplicate` — похожий документ уже есть в 1С или в очереди; `cap` — потолок суммы (документа, дня сценария или компании) или числа карточек справочника за запуск; `write_unknown` — исход записи в 1С неизвестен, документ мог появиться, сумма занимает потолок: при `failed` — 1С не ответила на запись (или процесс прервался посреди неё), повтор запуска найдёт документ по метке [AI P-…]; при `skipped` — повтор такой записи сам не дописал (почему — reason), решает человек: «Записать» найдёт документ по метке. Нет поля — другая причина, см. reason"""
    duplicate_of: str | None = None
    """Повтор запуска подготовил тот же документ, что прошлая попытка: это предложение отозвано, в силе указанное (id предложения)"""
    id: str = MISSING
    """id предложения (документа для 1С), подготовленного запуском; карточка — GET /v1/companies/{co}/proposals/{id}"""
    reason: str | None = None
    """Почему не записано само (при skipped и failed) — текст для человека, показать как есть"""


class AutomationRunProposalStatus(BaseModel):
    """Предложение запуска с его статусом сейчас."""

    attempt: int = MISSING
    """В какой попытке запуска подготовлено: 1 — первая, дальше — повторы"""
    auto: AutomationRunProposalStatusAuto | None = None
    """Итог автоодобрения: `approved` — записано в 1С и проведено само; `draft` — записано само черновиком, без проведения; `skipped` — само не записано, ждёт человека (почему — reason); `failed` — пыталось записать, но запись не удалась (reason). Нет поля — у сценария нет правила автоодобрения или предложение — повтор (duplicate_of)"""
    batch: bool | None = None
    """true — предложение собрано пачкой (выписка, входящие ЭСФ) или выпиской DirectBank, а не отдельным propose_* хода ИИ"""
    code: AutomationRunProposalStatusCode | None = None
    """Машинная причина (при skipped и failed): `status` — предложение уже не ждёт решения (его решили раньше); `kind` — вид документа не входит в правило; `level` — ИИ не доверено записывать такой вид без человека (PUT …/autonomy); `duplicate` — похожий документ уже есть в 1С или в очереди; `cap` — потолок суммы (документа, дня сценария или компании) или числа карточек справочника за запуск; `write_unknown` — исход записи в 1С неизвестен, документ мог появиться, сумма занимает потолок: при `failed` — 1С не ответила на запись (или процесс прервался посреди неё), повтор запуска найдёт документ по метке [AI P-…]; при `skipped` — повтор такой записи сам не дописал (почему — reason), решает человек: «Записать» найдёт документ по метке. Нет поля — другая причина, см. reason"""
    duplicate_of: str | None = None
    """Повтор запуска подготовил тот же документ, что прошлая попытка: это предложение отозвано, в силе указанное (id предложения)"""
    id: str = MISSING
    """id предложения (документа для 1С), подготовленного запуском; карточка — GET /v1/companies/{co}/proposals/{id}"""
    reason: str | None = None
    """Почему не записано само (при skipped и failed) — текст для человека, показать как есть"""
    status: str | None = None
    """Статус предложения сейчас: `previewed` — ждёт решения; `approved` — одобрено, ещё не записано; `rejected` — отклонено (или отозвано как повтор); `committed` — записано в 1С черновиком; `posted` — проведено; `verified` — проведено и сверено; `mismatch` — проведено, но проводки разошлись с ожидаемыми; `failed` — ошибка записи в 1С; `missing` — предложение не найдено. Нет поля — статус сейчас не узнать (компания не подключена к 1С)"""


class AutomationRunStep(BaseModel):
    """Итог шага запуска."""

    action: AutomationRunStepAction | None = MISSING
    """`agent` — ход ИИ (платный); `checks` — проверки учёта; `directbank` — опрос выписки DirectBank; `notify` — вебхук automation.run.notice разработчику; null — шаг ещё не начинался"""
    answer: str | None = MISSING
    """Итог шага текстом: ответ ИИ, итог проверок или опроса выписки"""
    error: str | None = MISSING
    """Почему шаг упал — текст для человека"""
    error_code: str | None = MISSING
    """Машинная причина: `onec_offline` — 1С не на связи (запуск повторится сам с этого шага)"""
    findings: int | None = MISSING
    """Сколько находок у проверок (checks); null — у других шагов"""
    output: dict[str, AutomationRunStepOutputValue] | None = MISSING
    """Итог шага agent в форме output"""
    output_error: AutomationRunStepOutputError | None = MISSING
    """Почему у шага agent нет итога"""
    output_note: str | None = MISSING
    """То же словами"""
    proposals: list[str] = MISSING
    """Предложения, подготовленные шагом (у directbank — выпиской; их одобряет правило auto_approve.directbank)"""
    skipped_by: AutomationRunStepSkippedBy | None = MISSING
    """Какое условие when не выполнилось (у skipped)"""
    state: AutomationRunStepState = MISSING
    """`done` — выполнен; `error` — упал (с него продолжит повтор); `skipped` — пропущен по условию when (skipped_by) или пробным прогоном (шаг directbank в пробном запуске банк не опрашивает, причина — в answer); `cancelled` — остановлен отменой; `pending` — ещё не дошёл"""
    step: int = MISSING
    """Номер шага, с 1"""
    stop_reason: str | None = MISSING
    """Почему остановился ход ИИ (у agent)"""


class AutomationScenario(BaseModel):
    """Сценарий автоматизации компании: триггер (когда) + действие (что)."""

    action: AutomationScenarioAction = MISSING
    """Старая форма: действие (у цепочки — первого шага, полностью — steps). `agent` — ход ИИ-бухгалтера по поручению instruction (готовит предложения — документы для 1С); `checks` — проверки учёта без ИИ и без предложений; `directbank` — опрос выписки DirectBank без ИИ (предложения — выпиской дня)"""
    auto_approve: AutomationAutoApprove | None = MISSING
    """Правило автоодобрения; null — всё подготовленное ждёт решения человека"""
    created_at: str = MISSING
    """Когда заведён, ISO 8601 UTC"""
    enabled: bool = MISSING
    """Включён ли. Выключенный не запускается событием и расписанием; вручную — запускается"""
    id: str = MISSING
