    linked: bool | None = None
    """true — ЭСФ уже привязан к документу в 1С"""
    status: EsfIncomingMatchStatus = MISSING
    """matched — найдено поступление; ambiguous — подходит несколько (candidates); not_found — не найдено; counterparty_unknown — поставщика нет в 1С; no_documents — у поставщика нет документов"""


