class WebhookEventAutomationRunCompletedData(BaseModel):
    """Данные события — только id, суммы, токены, статусы и время, без персональных данных"""

    action: str | None = MISSING
    """Что делал сценарий: agent — ход ИИ, checks — проверки, directbank — опрос выписки DirectBank, notify — уведомление; у цепочки — действие упавшего (или последнего) шага; null — сценарий удалён"""
    attempt: int = MISSING
    """Номер попытки (повтор — следующая)"""
    cost_tiyn: int = MISSING
    """Стоимость запуска, в тиынах (1 ₸ = 100 тиын)"""
    event_id: str | None = MISSING
    """Событие хука, которое запустило — тот же event_id, что вернул приём; null — запуск не по хуку (hev_…)"""
    external_id: str | None = MISSING
    """id этого события у отправителя хука (по id_path, Idempotency-Key или X-Event-Id); у события Tungo — его id evt_…; у пробного события хука — trial:…; null — запуск не по событию"""
    failed_step: int | None = MISSING
    """У цепочки шагов — номер упавшего шага (с 1): повтор продолжит с него; null — успешно или сценарий из одного шага"""
    finished_at: str | None = MISSING
    """Конец"""
    output: dict[str, WebhookEventAutomationRunCompletedDataOutputValue] | None = MISSING
    """Итог в форме сценария (output сценария): числа, да/нет, значения из списка и номера. null — формы нет, ИИ итог не вернул или он не прошёл проверку"""
    output_error: WebhookEventAutomationRunCompletedDataOutputError | None = MISSING
    """Почему output нет: not_returned — ИИ не отдал итог, rejected — отдал не в заданной форме; null — итог есть или формы нет"""
    proposal_ids: list[str] = MISSING
    """Предложения, подготовленные запуском"""
    proposals: list[WebhookEventAutomationRunCompletedDataProposalItem] = MISSING
    """Те же предложения (кроме отозванных повторов) с итогом: вид, статус, автоодобрение, сумма, номер и дата документа в 1С"""
    run_id: str = MISSING
    """Запуск — GET /v1/companies/{co}/automations/runs/{id} (run_…)"""
    scenario_id: str = MISSING
    """Сценарий (scn_…)"""
    started_at: str | None = MISSING
    """Начало"""
    state: str = MISSING
    """done — успешно, error — ошибка"""
    stop_reason: str | None = MISSING
    """Почему агент остановился"""
    trial: bool = MISSING
    """true — пробный прогон (на прошлом событии или на пробном событии хука): в 1С само ничего не записано, предложения ждут человека"""
    trigger: str = MISSING
    """Что запустило: hook, event (событие внутри Tungo), schedule, manual; directbank — заход опроса выписки собрал предложения для правила автоодобрения"""


